/**
 * Resolve a dashboard area id or display name to the NSW projection lgaName.
 * Returns undefined if no match is found.
 */
export function resolveProjectionName(areaIdOrName: string): string | undefined {
  const key = areaIdOrName.toLowerCase().trim();
  // 1. Try direct mapping
  if (AREA_TO_PROJECTION_NAME[key]) return AREA_TO_PROJECTION_NAME[key];
  // 2. Try exact match in PROJECTION_LGAS (case-insensitive)
  const exact = PROJECTION_LGAS.find(n => n.toLowerCase() === key);
  if (exact) return exact;
  // 3. Try starts-with match
  const starts = PROJECTION_LGAS.find(n => n.toLowerCase().startsWith(key) || key.startsWith(n.toLowerCase()));
  if (starts) return starts;
  return undefined;
}

/**
 * Get the full annual projection series for a given dashboard area id or name.
 * Returns an array sorted by year, or empty array if not found.
 */
export function getProjectionsForArea(areaIdOrName: string): NSWProjection[] {
  const lgaName = resolveProjectionName(areaIdOrName);
  if (!lgaName) return [];
  return getProjectionsForLGA(lgaName);
}

/**
 * Get a single projection value for a dashboard area id or name and year.
 */
export function getProjectionForArea(areaIdOrName: string, year: number): NSWProjection | undefined {
  const lgaName = resolveProjectionName(areaIdOrName);
  if (!lgaName) return undefined;
  return getProjection(lgaName, year);
}
